def hash_plain_passwords(apps, schema_editor):
    """Переводит пароли, хранившиеся открытым текстом, в хэши"""
    Account = apps.get_model('api', 'Account')
    for account in Account.objects.all():
        try:
            identify_hasher(account.password)  # уже хэш — пропускаем
        except ValueError:
            account.password = make_password(account.password)
            account.save(update_fields=['password'])


